import{_ as n,o as a,c as t,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Workspace timezone consistency — sửa lỗi Content Request deadline","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/workspace-timezone-consistency/spec.md","filePath":"feature/agency-workspace/workspace-timezone-consistency/spec.md"}'),c={name:"feature/agency-workspace/workspace-timezone-consistency/spec.md"};function o(s,e,r,h,l,d){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="workspace-timezone-consistency-—-sua-loi-content-request-deadline" tabindex="-1">Workspace timezone consistency — sửa lỗi Content Request deadline <a class="header-anchor" href="#workspace-timezone-consistency-—-sua-loi-content-request-deadline" aria-label="Permalink to &quot;Workspace timezone consistency — sửa lỗi Content Request deadline&quot;">​</a></h1><p>2026-10-14. User yêu cầu fix sau inventory Workspace 864f1df2-d0c9-4b74-8c3a-29ab63cccb97. Phạm vi: sửa contract đọc/ghi timezone, không thay quy tắc deadline hoặc quyền Workspace.</p><h2 id="nguon-va-nguyen-nhan" tabindex="-1">Nguồn và nguyên nhân <a class="header-anchor" href="#nguon-va-nguyen-nhan" aria-label="Permalink to &quot;Nguồn và nguyên nhân&quot;">​</a></h2><p><a href="./../../media-package-campaign/request-completion-validation/spec.html">Content Request deadline</a>, <a href="./../duplicate-workspace/spec.html">Duplicate Workspace</a>. Campaign hợp lệ nhưng UI đọc settings.timezone=null, trong khi ContentRequestDeadline kiểm timezone_config=Asia/Ho_Chi_Minh. Inventory chỉ đọc local: 124 Workspace active, 124 thiếu settings.timezone, không có cặp timezone khác nhau tại snapshot.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>timezone_config là nguồn chuẩn đã được Backend dùng cho deadline. Mọi WorkspaceResponse vẫn trả settings.timezone (không đổi API shape) nhưng lấy giá trị từ timezone_config, cả GET/list/create/update.</li><li>Đọc Workspace không sửa JSON/data cũ; giữ defaultPlatforms và industryFields hiện có.</li><li>Đổi timezone trong Settings phải validate ZoneId, rồi ghi timezone_config và settings.timezone cùng transaction. Payload sai/blank trả 400 VALIDATION_ERROR với fields.timezone, không ghi/name change.</li><li>Partial update không có timezone giữ nguyên cột chuẩn, không lấy JSON cũ ghi đè timezone_config.</li><li>Workspace mới giữ default hiện có Asia/Ho_Chi_Minh; không tự chọn theo máy/người dùng.</li><li>Nhân bản copyTimezone=true sao chép cột chuẩn — timezone API hiển thị và Backend kiểm deadline; false giữ default hiện có. Không đổi member/resource/package/campaign copy policy.</li><li>Giữ xác thực/phân quyền và deadline max(today,start)..end; không hardcode timezone ở frontend.</li><li>Không chạy migration, seed hoặc backfill DB trong đợt sửa này. Metadata dư không bị xóa.</li></ul><h2 id="ui-ux-va-out-of-scope" tabindex="-1">UI/UX và out of scope <a class="header-anchor" href="#ui-ux-va-out-of-scope" aria-label="Permalink to &quot;UI/UX và out of scope&quot;">​</a></h2><p>Không sửa JSX/layout/i18n/theme; useRequestDeadline tiếp tục đọc settings.timezone như hiện tại. Request date picker min/max và vi/en messages giữ nguyên. Không đổi auth, Campaign timeline hoặc Task workflow. Không đổi JDK/Lombok hay khởi động service có seeders trong quá trình test.</p>',8)])])}const g=n(c,[["render",o]]);export{p as __pageData,g as default};
